    /** A campaign reaches every enabled customer at or above a tier, one transaction per customer; the campaign code keeps re-runs from issuing twice. */
    @PostMapping("/member-offers/campaign") public String campaign(@AuthenticationPrincipal SessionUser user,@RequestParam(defaultValue="")String campaign,@RequestParam(defaultValue="")String minTier,@RequestParam(required=false)Long voucherId,@RequestParam(defaultValue="1")int count,@RequestParam(required=false)Long productId,@RequestParam(defaultValue="")String message,org.springframework.web.servlet.mvc.support.RedirectAttributes flash){
        try{String key=vn.cineprime.member.WalletService.campaignName(campaign);if(voucherId==null&&productId==null&&message.isBlank())throw new IllegalArgumentException("Chọn voucher, quà hoặc nhập nội dung thông báo.");if(count<1||count>10)throw new IllegalArgumentException("Số voucher mỗi khách từ 1 đến 10.");if(message.length()>2000)throw new IllegalArgumentException("Thông báo tối đa 2.000 ký tự.");
            List<Long> ids=wallet.audience(minTier);int reached=0,items=0,failed=0;String last="";
            for(Long id:ids)try{int n=wallet.campaign(user.id(),id,voucherId,count,productId,key,message.isBlank()?null:message);items+=n;if(n>0||voucherId==null&&productId==null)reached++;}catch(IllegalArgumentException e){failed++;last=e.getMessage();}
            db.audit(user.id(),"MEMBER_CAMPAIGN",key+" · "+ids.size()+" khách · "+items+" mục"+(failed>0?" · "+failed+" lỗi":""));
            flash.addFlashAttribute(failed>0?"actionError":"notice","Chiến dịch "+key+": "+ids.size()+" khách đủ điều kiện, "+reached+" khách nhận mới, "+items+" voucher/quà."+(failed>0?" "+failed+" khách lỗi: "+last:""));
        }catch(IllegalArgumentException e){flash.addFlashAttribute("actionError",e.getMessage());}
        return "redirect:/admin/member-offers";
    }
